SELECT DATE_FORMAT(expense_time, '%m-%d') AS NAME,
       IFNULL(SUM(price), 0) AS VALUE
FROM expense
WHERE activity_id = #{activityId}
  AND expense_time >= #{startDate}
  AND expense_time < #{endDate}
  AND positive = #{isExpense}
GROUP BY DATE(expense_time)
ORDER BY DATE(expense_time)

SELECT LPAD(DAY(expense_time), 2, '0') AS NAME,
       IFNULL(SUM(price), 0) AS VALUE
FROM expense
WHERE activity_id = #{activityId}
  AND YEAR(expense_time) = #{year}
  AND MONTH(expense_time) = #{month}
  AND positive = #{isExpense}
GROUP BY DAY(expense_time)
ORDER BY DAY(expense_time)

SELECT CONCAT(MONTH(expense_time), '月') AS NAME,
       IFNULL(SUM(price), 0) AS VALUE
FROM expense
WHERE activity_id = #{activityId}
  AND YEAR(expense_time) = #{year}
  AND positive = #{isExpense}
GROUP BY MONTH(expense_time)
ORDER BY MONTH(expense_time)

SELECT type AS NAME,
       IFNULL(SUM(price), 0) AS VALUE
FROM expense
WHERE activity_id = #{activityId}
  AND expense_time >= #{startDate}
  AND expense_time < #{endDate}
  AND positive = #{isExpense}
GROUP BY type
ORDER BY SUM(price) DESC

SELECT type AS NAME,
       IFNULL(SUM(price), 0) AS VALUE
FROM expense
WHERE activity_id = #{activityId}
  AND YEAR(expense_time) = #{year}
  AND MONTH(expense_time) = #{month}
  AND positive = #{isExpense}
GROUP BY type
ORDER BY SUM(price) DESC

SELECT type AS NAME,
       IFNULL(SUM(price), 0) AS VALUE
FROM expense
WHERE activity_id = #{activityId}
  AND YEAR(expense_time) = #{year}
  AND positive = #{isExpense}
GROUP BY type
ORDER BY SUM(price) DESC
